<?php require 'config.php';$u=me();$pct=setting('student_pct',50);$mode=($_GET['mode']??'intercity')=='local'?'local':'intercity';head('Find buses');
$f=trim($_GET['from']??'');$t=trim($_GET['to']??'');$d=$_GET['date']??'';if($d)ensure_trips($d);else for($i=0;$i<7;$i++)ensure_trips(date('Y-m-d',strtotime("+$i days")));
$rows=q("SELECT t.*,r.from_city,r.to_city,r.fare,b.reg_number,b.capacity,b.operator,(SELECT COUNT(*) FROM bookings k WHERE k.trip_id=t.id AND k.active=1) taken,(SELECT CONCAT(sa.name,'|',a.offset_min,'|',sz.name,'|',z.offset_min,'|',COALESCE(a.fare_at,r.fare*a.offset_min/NULLIF((SELECT MAX(m.offset_min) FROM route_stops m WHERE m.route_id=r.id),0),0),'|',COALESCE(z.fare_at,r.fare*z.offset_min/NULLIF((SELECT MAX(m.offset_min) FROM route_stops m WHERE m.route_id=r.id),0),0),'|',a.stop_id,'|',z.stop_id,'|',COALESCE((SELECT sf.fare FROM stop_fares sf WHERE sf.from_stop=a.stop_id AND sf.to_stop=z.stop_id),-1)) FROM route_stops a JOIN stops sa ON sa.id=a.stop_id JOIN route_stops z ON z.route_id=a.route_id AND z.seq>a.seq JOIN stops sz ON sz.id=z.stop_id WHERE a.route_id=r.id AND sa.name LIKE ? AND sz.name LIKE ? ORDER BY a.seq,z.seq LIMIT 1) seg
 FROM trips t JOIN routes r ON r.id=t.route_id JOIN buses b ON b.id=t.bus_id WHERE b.status='approved' AND r.type=? AND EXISTS(SELECT 1 FROM route_stops a JOIN stops sa ON sa.id=a.stop_id JOIN route_stops z ON z.route_id=a.route_id AND z.seq>a.seq JOIN stops sz ON sz.id=z.stop_id WHERE a.route_id=r.id AND sa.name LIKE ? AND sz.name LIKE ?) AND ((?='' AND t.depart_date>=CURDATE()) OR t.depart_date=?) AND t.status<>'cancelled' ORDER BY t.depart_date,t.depart_time",["%$f%","%$t%",$mode,"%$f%","%$t%",$d,$d])->fetchAll();?>
<div class="tabs"><a class="btn <?=$mode=='local'?'':'ghost'?>" href="search.php?mode=local">Local bus</a> <a class="btn <?=$mode=='intercity'?'':'ghost'?>" href="search.php?mode=intercity">Long-distance bus</a></div><h2><?=$mode=='local'?'Local buses':'Long-distance buses'?></h2><?php if($u&&is_student($u))echo '<p class="flash">Student discount active: you get '.$pct.'% off every fare.</p>';?>
<form class="row card" method="get"><input type="hidden" name="mode" value="<?=$mode?>"><label>From<input name="from" list="cities" value="<?=e($f)?>"></label><button type="button" class="btn ghost" title="Swap From and To" onclick="var a=this.form.from,b=this.form.to,t=a.value;a.value=b.value;b.value=t">⇄</button><label>To<input name="to" list="cities" value="<?=e($t)?>"></label><datalist id="cities"><?php foreach(q("SELECT DISTINCT s.name c FROM stops s JOIN route_stops rs ON rs.stop_id=s.id JOIN routes r ON r.id=rs.route_id WHERE r.type='$mode' ORDER BY s.name")->fetchAll() as $c)echo '<option value="'.e($c['c']).'">';?></datalist><label>Date<input type="date" name="date" value="<?=e($d)?>"></label><button class="btn">Search</button></form>
<?php if(!$rows){$alt=$mode=='local'?'intercity':'local';$has=q("SELECT 1 FROM routes r WHERE r.type=? AND EXISTS(SELECT 1 FROM route_stops a JOIN stops sa ON sa.id=a.stop_id JOIN route_stops z ON z.route_id=a.route_id AND z.seq>a.seq JOIN stops sz ON sz.id=z.stop_id WHERE a.route_id=r.id AND sa.name LIKE ? AND sz.name LIKE ?) LIMIT 1",[$alt,"%$f%","%$t%"])->fetch();
 echo '<p class="card">No buses match here.'.($has?' This route runs as a <strong>'.($alt=='local'?'local bus':'long-distance bus').'</strong>. <a href="search.php?'.http_build_query(['mode'=>$alt,'from'=>$f,'to'=>$t,'date'=>$d]).'">Show those buses</a>.':' Try a different route or clear the date.').'</p>';}
foreach($rows as $r){$free=$r['capacity']-$r['taken'];$sg=explode('|',(string)$r['seg']);$seg=$f!==''&&$t!==''&&isset($sg[7]);if($seg)$r['fare']=(isset($sg[8])&&(float)$sg[8]>=0)?max(1,round((float)$sg[8])):max(1,round((float)$sg[5]-(float)$sg[4]));$bt=$seg?date('H:i',strtotime($r['depart_time'])+(int)$sg[1]*60):substr($r['depart_time'],0,5);?>
<div class="card trip"><div><h3><?=e($seg?$sg[0].' to '.$sg[2]:$r['from_city'].' to '.$r['to_city'])?></h3><div class="muted"><?=e($r['operator'])?> · <?=e($r['reg_number'])?> · <?=e($r['depart_date'])?> at <?=$bt?><?=$seg?' from '.e($sg[0]).' · on the '.e($r['from_city']).' to '.e($r['to_city']).' route':''?></div>
<span class="pill <?=e($r['status'])?>"><?=e($r['status'])?></span> <span class="pill"><?=$free?> seats left</span></div>
<div><?php $sf=round($r['fare']*(100-$pct)/100,2);if($mode=='local'&&$u&&is_student($u))echo '<div class="muted"><s>৳'.number_format($r['fare']).'</s></div><div class="big">৳'.number_format($sf).'</div><span class="pill verified">Student fare</span>';else echo '<div class="big">৳'.number_format($r['fare']).'</div>'.($mode=='local'?'<div class="muted">Student fare ৳'.number_format($sf).($u&&$u['student_status']=='pending'?' once verified':'').'</div>':'');?><?=strtotime($r['depart_date'].' '.$bt)<time()?'<span class="pill">Departed</span>':($free>0?'<a class="btn" href="book.php?trip='.$r['id'].($seg?'&from='.$sg[6].'&to='.$sg[7]:'').'">'.($mode=='local'?'Get ticket':'Select seat').'</a>':'<span class="pill cancelled">Sold out</span>')?></div></div>
<?php }foot();
